-- 1. Create the table matching the Session 11 worksheet schema\nCREATE TABLE entries (\n  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,\n  created_at timestamptz DEFAULT now(),\n  owner uuid REFERENCES auth.users NOT NULL,\n  question text NOT NULL,\n  answer_kh text NOT NULL,\n  answer_en text NOT NULL,\n  category text NOT NULL,\n  hint text,\n  explanation text,\n  source text NOT NULL\n);\n\n-- 2. Enable RLS and setup policies\nALTER TABLE entries ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY "Public profiles are viewable by everyone." ON entries\n  FOR SELECT USING (true);\n\nCREATE POLICY "Users can insert their own entries." ON entries\n  FOR INSERT WITH CHECK (auth.uid() = owner);\n\nCREATE POLICY "Users can update their own entries." ON entries\n  FOR UPDATE USING (auth.uid() = owner);\n\nCREATE POLICY "Users can delete their own entries." ON entries\n  FOR DELETE USING (auth.uid() = owner);\n\n-- 3. Insert initial riddles\n-- REPLACE <YOUR_USER_ID> with your actual Supabase auth.users UUID!\nDO $$\nDECLARE\n  my_user_id uuid := '<YOUR_USER_ID>';\nBEGIN\n  INSERT INTO entries (owner, question, answer_kh, answer_en, category, hint, explanation, source) VALUES\n  (my_user_id, 'ពេលនៅក្មេងស្លៀកសំពត់ខៀវ ដល់ពេលវ័យកណ្តាលស្លៀកសំពត់ក្រហម ដល់ចាស់ស្លៀកសំពត់ខ្មៅ តើជាអ្វី?', 'ផ្លែម្ទេស', 'Chili Pepper', 'Plants & Fruits', 'Dressed in blue when young, red when mature, black when old — what am I?', 'The riddle maps the color stages of a chili pepper as it ripens: green when young, red when ripe, and dark/black when dried and withered.', 'Buddhist Institute of Cambodia, Collection of Ancient Khmer Riddles'),
  (my_user_id, 'ជើងបួនត្រដោក យំគោកៗ នៅតាមវាលស្រែ ដល់ពេលគេចាប់យកមកកែ ក្លាយជាម្ហូបឆ្ងាញ់?', 'កង្កែប / គីង្គក់', 'Frog', 'Nature & Animals', 'Four legs stomping, crying loudly across the rice fields — caught and turned into a delicacy?', 'A frog leaping through flooded rice paddies during the rainy season — a common sound of rural Cambodian life, and a traditional dish (grilled or pounded).', 'Khmer Folk Literature Heritage, Ministry of Culture and Fine Arts'),
  (my_user_id, 'ទៅកប់ត្រឡាច មកកប់ត្រឡាច ដើរមួយថ្ងៃមិនចេះហត់?', 'ស្នាមចែវ / ចែវទូក', 'Paddle strokes on water', 'Tools & Farming', 'Buries going forward, buries coming back — walks all day without tiring?', 'The motion of paddling a boat — the blade plunges into the water going and coming, yet leaves no lasting trace. A beautiful observation of impermanence from daily river life.', 'Ancient Khmer Riddles, Buddhist Institute of Cambodia'),
  (my_user_id, 'ដើរកាត់ព្រៃមិនបែក ធ្លាក់ក្នុងទឹកមិនលិច ត្រូវភ្លើងមិនឆេះ តើជាអ្វី?', 'ស្រមោល', 'Shadow', 'Body & Daily Life', 'Walks through the forest without breaking branches, falls in water without drowning, touches fire without burning?', 'The shadow is an intangible companion that follows us everywhere — it cannot be destroyed by forest, water, or fire. A meditation on the formless things that are always with us.', 'Collection of Khmer Folk Riddles, Buddhist Institute of Cambodia'),
  (my_user_id, 'ដើមមួយមានមែកបួន មែកនីមួយៗមានស្លឹកប្រាំ?', 'ដៃ ជើង និងម្រាម', 'Human hands and feet (arms & legs with five fingers/toes each)', 'Body & Daily Life', 'One tree with four branches, each branch bearing five leaves?', 'The human body compared to a tree: the trunk is the torso, four branches are two arms and two legs, and five leaves on each branch are the five fingers or toes. Used to teach children anatomy through poetry.', 'Khmer Folk Literature for Children, National Library of Cambodia'),
  (my_user_id, 'មានខ្លួនគ្មានក្បាល មានពោះគ្មានពោះវៀន ចុកពោះម្ដងៗស្រែកទ្រហោយំ?', 'ស្គរ', 'Traditional Khmer Drum (Skhor)', 'Tools & Farming', 'Has a body but no head, has a belly but no intestines — poke its belly and it cries out loud?', 'The traditional Khmer drum: a hollow body with no head, an empty resonant belly — and when struck, it produces a powerful sound that can carry across villages and temple grounds.', 'Traditional Khmer Music & Arts Heritage, Ministry of Culture and Fine Arts'),
  (my_user_id, 'កំប៉ុកក្រពុំ អង្គុយលើភ្នំ រំសាយសក់លេង តើជាអ្វី?', 'ផ្លែពោត', 'Ear of Corn', 'Plants & Fruits', 'Plump and budding, sitting atop a hill, letting her long hair flow in the wind — what am I?', 'A poetic observation of an ear of corn growing on its stalk, with its golden silk tassels blowing freely in the breeze like long, flowing hair.', 'Ancient Khmer Riddles & Proverbs (Compiled by Pich Sal)'),
  (my_user_id, 'កាប់មួយទឹះត្រូវថ្ម កាប់មួយទឹះត្រូវដីស កាប់មួយទឹះត្រូវទឹកសមុទ្រ តើជាអ្វី?', 'ផ្លែដូង', 'Coconut', 'Plants & Fruits', 'One strike hits stone, one strike hits chalk, one strike hits sea water — what am I?', 'Opening a fresh coconut layer by layer: striking through the hard fibrous shell (stone), slicing into the white meat (chalk), and drinking the sweet water (sea).', 'Collection of Khmer Riddles (Compiled by Chey Chap, Buddhist Institute)'),
  (my_user_id, 'កំប៉េងកំប៉ោះ កំប៉េងឥតដោះ ចិញ្ចឹមកូនរស់ តើជាអ្វី?', 'មេមាន់', 'Mother Hen', 'Nature & Animals', 'Bustling and clucking with no milk to give, yet raises all her young to thrive — what am I?', 'Praising maternal diligence in traditional Cambodian villages: the hen has no milk to nurse her chicks, yet through tireless scratching and foraging, she nurtures her brood to adulthood.', 'Ancient Khmer Riddles & Proverbs (Compiled by Pich Sal)'),
  (my_user_id, 'កាន់កន្ទុយញាក់ខ្សែ អាចម៍មួយស្រែ មិនស្អុយសោះ តើជាអ្វី?', 'នង្គ័ល / មនុស្សភ្ជួរស្រែ', 'Farmer & Traditional Plow', 'Tools & Farming', 'Holding the tail and twitching the reins, leaving droppings across the whole field without any foul smell — what am I?', 'A farmer plowing the rice paddy: holding the handle (''tail'') and twitching the reins, turning up dark, fertile furrows of fresh earth (''droppings'') across the field.', 'Ancient Khmer Riddles & Proverbs (Compiled by Pich Sal)'),
  (my_user_id, 'មានជើងមិនចេះដើរ មានស្លាបមិនចេះហើរ មានមាត់មិនចេះស្ដី តើជាអ្វី?', 'ផ្ទះខ្មែរ', 'Traditional Khmer Stilt House', 'Body & Daily Life', 'Has legs but cannot walk, has wings but cannot fly, has a mouth but cannot speak — what am I?', 'The anatomical metaphor for a traditional Khmer wooden house: the wooden foundation stilts are ''legs'', the sheltering eaves are ''wings'', and the front entrance is the ''mouth''.', 'Khmer Folk Literature Heritage, Ministry of Culture and Fine Arts'),
  (my_user_id, 'ដាំមិនដុះ ពុះមិនបែក ហែកមិនដាច់ តើជាអ្វី?', 'ទឹក', 'Water', 'Wisdom & Folklore', 'Cannot be planted to grow, cannot be chopped to split, cannot be torn to pieces — what am I?', 'A famous philosophical riddle on the elemental nature of water: essential to all life, yet formless, indivisible, and impossible to cut or tear apart.', 'Ancient Khmer Riddles & Wisdom Puzzles, Buddhist Institute of Cambodia');\nEND $$;